--
-- Name: vw_ventas_apicultor_municipio; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_ventas_apicultor_municipio AS
 SELECT ub.departamento,
    ub.municipio,
    u.usuario_id AS cod_apicultor,
    u.nombre_usuario AS apicultor,
    count(DISTINCT pe.pedido_id) AS total_pedidos,
    sum((dp.cantidad * dp.precio_unitario)) AS total_ventas_cop
   FROM (((((public.usuario u
     JOIN public.publicacion pub ON ((u.usuario_id = pub.usuario_id)))
     JOIN public.detalle_pedido dp ON ((pub.publicacion_id = dp.publicacion_id)))
     JOIN public.pedido pe ON ((dp.pedido_id = pe.pedido_id)))
     JOIN public.mercado m ON ((pe.mercado_id = m.mercado_id)))
     JOIN public.ubicacion ub ON ((m.ubicacion_id = ub.ubicacion_id)))
  WHERE (u.rol_id = 2)
  GROUP BY ub.departamento, ub.municipio, u.usuario_id, u.nombre_usuario
 HAVING (sum((dp.cantidad * dp.precio_unitario)) > (500000)::numeric)
  ORDER BY (sum((dp.cantidad * dp.precio_unitario))) DESC;


ALTER VIEW public.vw_ventas_apicultor_municipio OWNER TO postgres;

